-- 00_readonly_precheck.sql: SELECT only. Confirms every guarded edit in 01_ask_kb_nationwide.sql still finds its old phrase
-- in the live rows, and that the new ids are free. Expect: edits = old_phrase_found, missing null, id_clash 0.
select count(*) as edits, count(*) filter (where k.ord is not null and k.chunk->>'id' = v.id and strpos(k.chunk->>v.f, v.old) > 0) as old_phrase_found,
 string_agg(v.ord::text, ',') filter (where k.ord is null or k.chunk->>'id' <> v.id or strpos(k.chunk->>v.f, v.old) = 0) as missing,
 (select max(ord) from pb_ai.kb_chunks where version='b3e91f6c47d2') as max_ord,
 (select count(*) from pb_ai.kb_chunks where version='b3e91f6c47d2' and (chunk->>'id' like 'dig-%' or chunk->>'id' like 'plan-%')) as id_clash
from (values
(71,'app-howto-locates-1','text',$p$Each ticket shows Can dig from (2 working days after the call, the call day not counted) and Start work by (14 days after the call); a ticket is good for 28 days (Settings › Company: "A new dig ticket is good for (days)").$p$),
(235,'app-data-other-reference-values-2','text',$p$a ticket is good for 28 days (company setting 1–60, default 28).$p$),
(1912,'quick-reference-4','text',$p$ and in shallower trenches if a cave-in is possible; Washington requires it at 4 ft (WAC 296-155-657), and California also needs a Cal/OSHA permit at 5 ft (8 CCR 341). Over 20 ft$p$),
(1912,'quick-reference-4','text',$p$Daily inspection by the competent person, and after rain.$p$),
