(1913,'quick-reference-5','source',$p$Iowa One Call manual$p$),
(1913,'quick-reference-5','text',$p$commonly 18 inches each side of the marked facility (Iowa) or 24 inches in many states$p$),
(2012,'utility-locates-3','text',$p$many states use 18 inches either side of the outside edge of the utility (Iowa: 18 inches each side, 36 inches total), others 24 inches$p$),
(2014,'utility-locates-5','text',$p$Iowa requires white-lining unless the location can be clearly described on the call or at a preconstruction meeting, electronic white-lining is used, or physical premarking is impractical.$p$),
(2015,'utility-locates-6','text',$p$(Iowa's manual says in an emergency leave equipment where it is)$p$),
